            )
        elif mode == "forward_stp":
            result, observer = _run_forward_stp(
                config, events, True, max_replay_work
            )
        elif mode == "forward_decode":
            result, observer = _run_forward_decode(
                config, events, True, max_replay_work
            )
        elif mode == "forward_check":
            result, observer = _run_forward_check(
                config, events, True, max_replay_work
            )
        elif mode == "stp_decode":
            result, observer = _run_stp_decode(
                config, events, True, max_replay_work
            )
        elif mode == "igmp_snoop_decode":
            result, observer = _run_igmp_snoop_decode(
                config, events, True, max_replay_work
            )
        elif mode == "mld_snoop_decode":
            result, observer = _run_mld_snoop_decode(
                config, events, True, max_replay_work
            )
        elif mode == "stp_check":
            result, observer = _run_stp_check(
                config, events, True, max_replay_work
            )
        elif mode == "forward_stp_storm":
            result, observer = _run_forward_stp_storm(
                config, events, True, max_replay_work
            )
        elif mode == "lag":
            result, observer = _run_lag(
                config, events, True, max_replay_work
            )
        elif mode == "mirror":
            result, observer = _run_mirror(
                config, events, True, max_replay_work
            )
        elif mode == "acl":
            result, observer = _run_acl(
                config, events, True, max_replay_work
            )
        elif mode == "security_check":
            result, observer = _run_security_check(
                config, events, True, max_replay_work
            )
        elif mode == "acl_check":
            result, observer = _run_acl_check(
                config, events, True, max_replay_work
            )
        elif mode == "qos":
            result, observer = _run_qos(
                config, events, True, max_replay_work
            )
        elif mode == "qos_check":
            result, observer = _run_qos_check(
                config, events, True, max_replay_work
            )
        elif mode == "qos_decode":
            result, observer = _run_qos_decode(
                config, events, True, max_replay_work
            )
        elif mode == "qos_wire_decode":
            result, observer = _run_qos_wire_decode(
                config, events, True, max_replay_work
            )
        elif mode == "qos_pfc_decode":
            result, observer = _run_qos_pfc_decode(
                config, events, True, max_replay_work
            )
        elif mode == "mirror_check":
            result, observer = _run_mirror_check(
                config, events, True, max_replay_work
            )
        elif mode == "lag_check":
            result, observer = _run_lag_check(
                config, events, True, max_replay_work
            )
        elif mode == "storm_check":
            result, observer = _run_storm_check(
                config, events, True, max_replay_work
            )
        else:
            result, observer = _run_reload(
                config, events, True, max_replay_work
            )
        _verify_records(
            log, observer.get("events", events), observer["items"]
        )
        # 重放重建的 LOG 须与原文件逐字节一致（含 sha256 与 LF）
        rebuilt = _build_log_doc(
            config, observer.get("events", events), observer["items"]
        )
        if _log_bytes(rebuilt) != log_raw:
            raise InvalidInput("bad log")
        # 输出上界在全部日志语义与重放核对成功后判定；LOG 保持不动
        output = _result_bytes(result)
        if len(output) > max_output_bytes:
            _fail("output_limit")
            return 5
    except InvalidInput:
        _fail("invalid_input")
        return 4
    except (
        ReloadWorkLimit,
        StpWorkLimit,
        LoopWorkLimit,
        FdbWorkLimit,
        ForwardWorkLimit,
        FdbCapacityWorkLimit,
        ForwardStpWorkLimit,
        LinkForwardWorkLimit,
        LinkWorkLimit,
        LinkWireWorkLimit,
        LinkFlowWorkLimit,
        SecurityWorkLimit,
        QosWorkLimit,
        QosWireWorkLimit,
        QosPfcWorkLimit,
        IgmpWorkLimit,
        MldWorkLimit,
        AclWorkLimit,
        MirrorWorkLimit,
        LagWorkLimit,
        StormWorkLimit,
    ):
        _fail("replay_work_limit")
        return 5
    sys.stdout.buffer.write(output)
    return 0


FILTER_DIGEST_KEYS = ("schema", "source_sha256", "records")


def _filter_prefix_bytes(doc):
    """log-filter 末项摘要文本：前三键紧凑 UTF-8 加 LF。"""
    prefix = {key: doc[key] for key in FILTER_DIGEST_KEYS}
    return (
        json.dumps(prefix, ensure_ascii=False, separators=(",", ":")) + "\n"
    ).encode("utf-8")


def _filter_bytes(doc):
    """log-filter stdout 载荷：四键紧凑 UTF-8 加 LF。"""
    ordered = {
        key: doc[key]
        for key in FILTER_DIGEST_KEYS + ("sha256",)
    }
    return (
        json.dumps(ordered, ensure_ascii=False, separators=(",", ":")) + "\n"
    ).encode("utf-8")


def _cmd_log_filter(
    log_path, start_token, end_token, applied_token,
    max_log_bytes, max_output_bytes,
):
    # START/END 为 * 或任意长度非负整数（按数学整数比较）；均非 * 时
    # START≤END；APPLIED 取 */true/false，否则 usage
    if _FILTER_BOUND_RE.fullmatch(start_token) is None:
        _fail("usage")
        return 2
    if _FILTER_BOUND_RE.fullmatch(end_token) is None:
        _fail("usage")
        return 2
    if applied_token not in ("*", "true", "false"):
        _fail("usage")
        return 2
    start = None if start_token == "*" else _limit_value(start_token)
    end = None if end_token == "*" else _limit_value(end_token)
    if start is not None and end is not None and start > end:
        _fail("usage")
        return 2
    want_applied = None if applied_token == "*" else (applied_token == "true")
    try:
        with open(log_path, "rb") as handle:
            # 分块至多 65536 字节读取，输入上限按原始字节计，等于上限合法
            log_raw = _read_limited(handle, max_log_bytes)
    except OSError:
        _fail("file_not_found")
        return 3
    if log_raw is None:
        _fail("log_limit")
        return 5
    try:
        # 仅静态校验：顶层/记录键序与字段类型、config/event 规范键序、
        # event 已知键形、内部 sha256；不校验配置语义、不重演事件，
        # 也不推导 version/applied/output
        log = parse_json(log_raw)
        _validate_log_shape(log)
        if hashlib.sha256(_log_prefix_bytes(log)).hexdigest() != log["sha256"]:
            raise InvalidInput("bad log sha256")
        kept = []
        for record in log["records"]:
            if start is not None and record["t"] < start:
                continue
            if end is not None and record["t"] > end:
                continue
            if want_applied is not None and record["applied"] is not want_applied:
                continue
            kept.append(record)
        # 原样记录（同对象）保留原序；schema 固定 1，source_sha256 取原摘要
        doc = {
            "schema": RECORD_SCHEMA,
            "source_sha256": log["sha256"],
            "records": kept,
        }
        doc["sha256"] = hashlib.sha256(_filter_prefix_bytes(doc)).hexdigest()
        payload = _filter_bytes(doc)
    except InvalidInput:
        _fail("invalid_input")
        return 4
    # 输出上界（含末尾 LF）在写出前判定；等于上限合法，失败 stdout 为空
    if len(payload) > max_output_bytes:
        _fail("output_limit")
        return 5
    sys.stdout.buffer.write(payload)
    return 0


SUMMARY_DIGEST_KEYS = ("schema", "source_sha256", "total", "applied", "kinds")
# kinds 固定全列此序，缺类补 0；kind 仅取静态事件键形，不重演推导。
# link-wire 的 advance 事件不追加到固定七类：仅当日志确含 advance 记录时
# 在末尾追加 "advance" 桶，无该类记录的既有日志字节逐字节不变。
SUMMARY_KINDS = (
    "learn", "frame", "link", "member", "service", "reload", "rollback",
)


def _summary_prefix_bytes(doc):
    """log-summary 末项摘要文本：前五键紧凑 UTF-8 加 LF。"""
    prefix = {key: doc[key] for key in SUMMARY_DIGEST_KEYS}
    return (
        json.dumps(prefix, ensure_ascii=False, separators=(",", ":")) + "\n"
    ).encode("utf-8")


def _summary_bytes(doc):
