STORM_CHECK_CONFIG_KEYS = frozenset(
    ("bridges", "links", "delay", "bridge", "ports", "age", "storm",
     "max_frame")
)


QOS_DECODE_FRAME_KEYS = FRAME_DECODE_FRAME_KEYS  # {"t", "port", "data"}

def validate_igmp_snoop_config(config):
    if (
        not isinstance(config, dict)
        or frozenset(config) != IGMP_SNOOP_CONFIG_KEYS
    ):
        raise InvalidInput("bad config")
    # 七键与 stp-decode（stp-check）完全一致，复用其全量校验
    bridges, links, delay, bridge, ports, age, max_frame = (
        validate_stp_check_config(
            {key: config[key] for key in STP_CHECK_CONFIG_KEYS}
        )
    )
    igmp = config["igmp"]
    if not isinstance(igmp, dict) or frozenset(igmp) not in (
        IGMP_KEYS, IGMP_ENHANCED_KEYS
    ):
        # 两键对象为兼容模式（校验与行为不变）；三键对象启用按 VLAN
        # 动态发现组播路由端口；其余形状（含未知键）即非法
        raise InvalidInput("bad igmp")
    membership_age = igmp["membership_age"]
    if not _is_int(membership_age) or membership_age <= 0:
        raise InvalidInput("bad igmp membership_age")
    router_ports = igmp["router_ports"]
    if not isinstance(router_ports, list):
        raise InvalidInput("bad igmp router_ports")
    name_set = {port["name"] for port in ports}
    for name in router_ports:
        if not isinstance(name, str) or name not in name_set:
            raise InvalidInput("bad igmp router port")
    if len(set(router_ports)) != len(router_ports):  # 端口名不重复
        raise InvalidInput("bad igmp router_ports")
    # 两键对象缺省为兼容模式（router_age 缺省 None）；三键对象启用增强，
    # router_age 必须为非布尔正整数（null/布尔/非正整数即非法）
    router_age = igmp.get("router_age") if "router_age" in igmp else None
    if "router_age" in igmp and (
        not _is_int(router_age) or router_age <= 0
    ):
        raise InvalidInput("bad igmp router_age")
    return (
        bridges, links, delay, bridge, ports, age, max_frame,
        membership_age, tuple(router_ports), router_age,
    )


def _internet_checksum(data):
    """IPv4/IGMP 反码求和校验；奇数尾字节补零，校验时整段求和须为 0。"""
    if len(data) % 2:
        data = data + b"\x00"
    total = 0
    for index in range(0, len(data), 2):
        total += (data[index] << 8) | data[index + 1]
    while total >> 16:
        total = (total & 0xFFFF) + (total >> 16)
    return (~total) & 0xFFFF


def _parse_igmp_outer(raw, ethertype_offset):
    """解析 IPv4 帧外层并定位未分片的 IGMP 报文。

    - 返回 None：非 IPv4/IGMP、IPv4 头非法或校验失败、任何分片，调用方按
      普通 IPv4 帧处理（组播沿用泛洪或成员投递）；
    - 返回 ("invalid",)：IPv4 外层合法且为未分片协议号 2，但 IPv4 总长度
      容纳不了最短 IGMP 报文或超过实际载荷，调用方固定输出 igmp_invalid；
    - 返回 ("ok", igmp_msg)：校验通过的外层，igmp_msg 为按 IPv4 总长度截
      取的完整 IGMP 报文（调用方按类型继续校验）。
    """
    payload = raw[ethertype_offset + 2:-4]
    if len(payload) < 20:
        return None
    version_ihl = payload[0]
    if version_ihl >> 4 != 4:
        return None
    ihl = version_ihl & 0x0F
    if ihl < 5:
        return None
    header_len = ihl * 4
    if len(payload) < header_len:
        return None
    if _internet_checksum(payload[:header_len]) != 0:  # IPv4 头校验
        return None
    fragment_word = (payload[6] << 8) | payload[7]
    # MF（bit13）或片偏移（bit0..12）非零：任何分片都不识别；DF 忽略
    if fragment_word & 0x3FFF:
        return None
    if payload[9] != IP_PROTOCOL_IGMP:
        return None
    total_length = (payload[2] << 8) | payload[3]
    # IGMPv2 报文最短 8 字节；容纳不了或超过实际载荷均为非法
    if total_length < header_len + 8 or total_length > len(payload):
        return ("invalid",)
    return ("ok", payload[header_len:total_length])


def _igmp_v2_from_msg(igmp_msg):
    """对已截取的 IGMP 报文做 IGMPv2 Query/Report/Leave 校验。"""
    mtype = igmp_msg[0]
    if mtype not in IGMP_CONTROL_ACTIONS:
        return ("invalid",)  # 类型非法（含 IGMPv3 等）
    if len(igmp_msg) != 8:
        return ("invalid",)  # IGMPv2 Query/Report/Leave 恰为 8 字节
    if _internet_checksum(igmp_msg) != 0:  # IGMP 校验
        return ("invalid",)
    octets = igmp_msg[4:8]
    group = ".".join(str(value) for value in octets)
    if mtype in (IGMP_TYPE_REPORT_V2, IGMP_TYPE_LEAVE_V2):
        if not 224 <= octets[0] <= 239:  # Report/Leave 组地址须为 D 类
            return ("invalid",)
    else:
        # Query：通用查询组地址 0.0.0.0 合法，组特定查询须为 D 类，
        # 其余组地址非法
        if tuple(octets) != (0, 0, 0, 0) and not 224 <= octets[0] <= 239:
            return ("invalid",)
    return ("ok", mtype, group)


def _ipv4_unicast(octets):
    """有效单播地址：首字节 1..223（A/B/C 类），排除 127 环回段；
    0.x 为本网、224+ 为组播/保留/广播。"""
    return 1 <= octets[0] <= 223 and octets[0] != 127

def _event_kind(event):
    if not isinstance(event, dict):
        raise InvalidInput("bad log event")
    kind = EVENT_KIND_BY_KEYS.get(frozenset(event))
    if kind is None:
        raise InvalidInput("bad log event")
    return kind


def _log_mode(config, events=None):
    """record/replay 按 config 形状选模式：fdb、forward、stp、loop-detect、
    link-forward、link-state、forward-static、forward-capacity、
    forward-stp、forward-check/
    forward-decode（共享 ports,age,max_frame 三键配置，按帧形状区分）、
    stp-check/stp-decode（共享七键配置，按事件帧形状区分）、
    forward-stp-storm、lag、mirror、acl、acl-check、qos、qos-check/
    qos-decode（共享十二键配置，按事件帧形状区分）、security-check、
    mirror-check、lag-check、storm-check、port-security，或 link-wire/
    link-wire-decode（共享含 queue_bytes 配置，按事件帧形状区分），或
    link-flow-decode（含 queue_bytes 与 flow_control 的端口配置，事件为
    原始帧形状），或 qos-wire-decode/qos-pfc-decode（共享含 queue_bytes、
    flow_control 与 qos 的配置，按每口是否均含 pfc 区分，混合即非法）。

    events 非 None 时用于区分共享配置形状的两种模式：三键配置的非空帧
    数组含 src（八键）按 forward-check，含 data（t/port/data 原始帧）按
    forward-decode；两种帧形状混用报 InvalidInput；空数组沿用既有
    forward-decode 路由（既有日志字节不变）。stp 七键配置的非链路帧含
    src（九键）按 stp-check，含 data（t/port/data 原始帧）按 stp-decode；
    两种帧形状混用报 InvalidInput；仅链路项或空事件沿用既有 stp-decode
    路由（既有日志字节不变）。stp 七键加 igmp 的配置按 igmp-snoop-decode
    （事件仅链路项与 t/port/data 原始帧）；stp 七键加 mld 的配置按
    mld-snoop-decode（事件外壳相同）。qos 十二键配置的帧项含 src（十键）按
    qos-check，含 data（t/port/data 原始帧）按 qos-decode，两种帧形状
    混用报 InvalidInput；仅链路/成员/service 项或空事件沿用既有
    qos-check 路由（既有日志字节不变）。link-wire 含 queue_bytes 配置的
    帧项含 src（九键）按 link-wire，含 data（t/port/data 原始帧）按
    link-wire-decode，两种帧形状混用报 InvalidInput；仅 link/advance 项
    或空事件沿用既有 link-wire 路由（既有日志字节与旧哈希不变）。
    """
    if isinstance(config, dict):
        keys = frozenset(config)
        # 恰含 ports,age 且 ports 为字符串数组时为 fdb 模式（forward 旧
        # 入口的 ports 为对象数组，形状不重叠）
        if keys == CONFIG_KEYS and isinstance(
            config.get("ports"), list
        ) and all(isinstance(p, str) for p in config["ports"]):
            return "fdb"
        # 恰含 ports,age 且 ports 为非空对象数组时为 forward 模式，旧式
        # access（name/vlan/up）与新式 802.1Q（name/mode/pvid/allowed/
        # untagged/up）两种端口形状均沿用 forward 入口识别与校验
        if (
            keys == CONFIG_KEYS
            and isinstance(config.get("ports"), list)
            and bool(config["ports"])
            and all(isinstance(p, dict) for p in config["ports"])
        ):
            return "forward"
        if keys == STP_CONFIG_KEYS:
            return "stp"
        if keys == LOOP_CONFIG_KEYS:
            return "loop"
        if keys == LINK_FORWARD_CONFIG_KEYS:
            # link-wire 与 link-forward 顶层同键，但端口形状不重叠：
            # link-wire 每口恰多 queue_bytes（八键），link-flow-decode 再
            # 多 flow_control（九键）。端口文档均含 flow_control 即按
            # link-flow-decode 路由（必同时含 queue_bytes，形状不全由全量
            # 校验判非法）；均含 queue_bytes 按 link-wire 系路由（事件可含
            # advance），其余沿用 link-forward。
            ports_doc = config.get("ports")
            if (
                isinstance(ports_doc, list)
                and ports_doc
                and all(
                    isinstance(p, dict) and "flow_control" in p
                    for p in ports_doc
                )
            ):
                # link-flow-decode 仅接受 {t,port,data} 原始帧（PAUSE 为
                # 其中一种），link/advance 同 link-wire；抽象帧与两种帧形
                # 状混用即非法输入；仅 link/advance 项或空事件亦按本模式
                # 路由。
                for event in events if isinstance(events, list) else ():
                    if not isinstance(event, dict):
                        raise InvalidInput("bad log event")
                    ekeys = frozenset(event)
                    if ekeys not in (
                        FRAME_DECODE_FRAME_KEYS,
                        LINK_WIRE_LINK_EVENT_KEYS,
                        LINK_WIRE_ADVANCE_EVENT_KEYS,
                    ):
                        raise InvalidInput("bad log event")
                return "link_flow_decode"
            elif (
                isinstance(ports_doc, list)
                and ports_doc
                and all(
                    isinstance(p, dict) and "queue_bytes" in p
                    for p in ports_doc
                )
            ):
                # link-wire 与 link-wire-decode 共享 queue_bytes 配置：
                # 帧项含 src（九键抽象帧）按 link-wire，含 data（t/port/
                # data 原始帧）按 link-wire-decode，两种帧形状混用即非法
                # 输入；仅 link/advance 项或空事件沿用既有 link-wire 路由
                # （既有日志字节与旧哈希逐字节不变）。
                saw_src = False
                saw_data = False
                for event in events if isinstance(events, list) else ():
                    if not isinstance(event, dict):
                        raise InvalidInput("bad log event")
                    ekeys = frozenset(event)
                    if ekeys == LINK_WIRE_FRAME_EVENT_KEYS:
                        saw_src = True
                    elif ekeys == FRAME_DECODE_FRAME_KEYS:
                        saw_data = True
                    elif ekeys not in (
                        LINK_WIRE_LINK_EVENT_KEYS,
                        LINK_WIRE_ADVANCE_EVENT_KEYS,
                    ):
                        raise InvalidInput("bad log event")
                if saw_src and saw_data:
                    raise InvalidInput("bad log event")
                return "link_wire_decode" if saw_data else "link_wire"
            return "link_forward"
        if keys == LINK_STATE_CONFIG_KEYS:
            return "link_state"
        if keys == FORWARD_STATIC_CONFIG_KEYS:
            return "forward_static"
        if keys == FORWARD_CAPACITY_CONFIG_KEYS:
            return "forward_capacity"
        if keys == FORWARD_STP_CONFIG_KEYS:
            return "forward_stp"
        if keys == FORWARD_CHECK_CONFIG_KEYS:
            # forward-check 与 forward-decode 共享三键配置：非空帧数组含
            # src（八键）按 forward-check，含 data 按 forward-decode，两种
            # 帧形状混用即非法输入；空数组沿用既有 forward-decode 路由
            saw_src = False
            saw_data = False
            for event in events if isinstance(events, list) else ():
                if not isinstance(event, dict):
                    raise InvalidInput("bad log event")
                ekeys = frozenset(event)
                if ekeys == FORWARD_CHECK_FRAME_KEYS:
                    saw_src = True
                elif ekeys == FRAME_DECODE_FRAME_KEYS:
                    saw_data = True
                else:
                    raise InvalidInput("bad log event")
            if saw_src and saw_data:
                raise InvalidInput("bad log event")
            return "forward_check" if saw_src else "forward_decode"
        if keys == IGMP_SNOOP_CONFIG_KEYS:
            # igmp-snoop-decode：stp-check 七键加 igmp；事件仅链路项与
            # t/port/data 原始帧，其余形状即非法输入
            for event in events if isinstance(events, list) else ():
                if not isinstance(event, dict):
                    raise InvalidInput("bad log event")
                ekeys = frozenset(event)
                if ekeys not in (STP_EVENT_KEYS, FRAME_DECODE_FRAME_KEYS):
                    raise InvalidInput("bad log event")
            return "igmp_snoop_decode"
        if keys == MLD_SNOOP_CONFIG_KEYS:
            # mld-snoop-decode：stp-check 七键加 mld；事件外壳与
            # igmp-snoop-decode 完全一致，仅链路项与 t/port/data 原始帧
            for event in events if isinstance(events, list) else ():
                if not isinstance(event, dict):
                    raise InvalidInput("bad log event")
                ekeys = frozenset(event)
                if ekeys not in (STP_EVENT_KEYS, FRAME_DECODE_FRAME_KEYS):
                    raise InvalidInput("bad log event")
            return "mld_snoop_decode"
        if keys == STP_CHECK_CONFIG_KEYS:
            # stp-check 与 stp-decode 共享七键配置：非链路帧含 src 按
            # stp-check，含 data 按 stp-decode，两种帧形状混用即非法输入
            saw_src = False
            saw_data = False
            for event in events if isinstance(events, list) else ():
                if not isinstance(event, dict):
                    raise InvalidInput("bad log event")
                ekeys = frozenset(event)
                if ekeys == STP_CHECK_FRAME_KEYS:
                    saw_src = True
                elif ekeys == FRAME_DECODE_FRAME_KEYS:
                    saw_data = True
                elif ekeys != STP_EVENT_KEYS:
                    raise InvalidInput("bad log event")
            if saw_src and saw_data:
                raise InvalidInput("bad log event")
            return "stp_check" if saw_src else "stp_decode"
        if keys == STORM_CONFIG_KEYS:
            return "forward_stp_storm"
        if keys == LAG_CONFIG_KEYS:
            return "lag"
        if keys == MIRROR_CONFIG_KEYS:
            return "mirror"
        if keys == ACL_CONFIG_KEYS:
            return "acl"
        if keys == ACL_CHECK_CONFIG_KEYS:
            return "acl_check"
        if keys == QOS_CONFIG_KEYS:
            return "qos"
        if keys == QOS_CHECK_CONFIG_KEYS:
            # qos-check 与 qos-decode 共享十二键配置：非链路/成员/service
            # 帧含 src（十键）按 qos-check，含 data（t/port/data 原始帧）
            # 按 qos-decode，两种帧形状混用即非法输入；无非帧帧项时沿用
            # 既有 qos-check 路由（既有日志字节不变）
            saw_src = False
            saw_data = False
            for event in events if isinstance(events, list) else ():
                if not isinstance(event, dict):
                    raise InvalidInput("bad log event")
                ekeys = frozenset(event)
                if ekeys == QOS_CHECK_FRAME_KEYS:
                    saw_src = True
                elif ekeys == FRAME_DECODE_FRAME_KEYS:
                    saw_data = True
                elif ekeys not in (
                    STP_EVENT_KEYS, MEMBER_EVENT_KEYS, SERVICE_EVENT_KEYS
                ):
                    raise InvalidInput("bad log event")
            if saw_src and saw_data:
                raise InvalidInput("bad log event")
            return "qos_decode" if saw_data else "qos_check"
        if keys == QOS_WIRE_CONFIG_KEYS:
            # qos-wire-decode 与 qos-pfc-decode 共享顶层五键（link-flow
            # 端口形状加 qos 子文档）：按每口 pfc 形状区分——所有端口文档
            # 均不含 pfc 按 qos-wire-decode，均含 pfc 按 qos-pfc-decode，
            # 混合或形状不全（ports 非非空对象数组）即非法输入。事件形状
            # 两者一致：仅 link/advance/{t,port,data} 原始帧，service 等
            # 其余形状一律非法输入；空事件或仅 link/advance 项均合法。
            ports_doc = config.get("ports")
            if not (
